INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM210HPEP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $7$ inches and a height of $11$ inches. What is the volume, in cubic inches, of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$77\\pi$"},{"key":"B","text":"$154\\pi$"},{"key":"C","text":"$539\\pi$"},{"key":"D","text":"$2156\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi (7)^2 (11) = \\pi (49)(11) = 539\\pi$ cubic inches. The answer $77\\pi$ results from computing $\\pi r h = \\pi(7)(11) = 77\\pi$, forgetting to square the radius. The answer $154\\pi$ results from using the lateral surface area formula $2\\pi r h = 2\\pi(7)(11) = 154\\pi$ instead of the volume formula. The answer $2156\\pi$ results from using the diameter $14$ instead of the radius: $\\pi(14)^2(11) = 2156\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM232EG44', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 250 registered voters in a city found that 58% plan to vote in favor of a proposed park expansion. The margin of error for the survey is 4 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 58% of all registered voters in the city plan to vote in favor of the park expansion."},{"key":"B","text":"Between 54% and 62% of the sampled voters plan to vote in favor of the park expansion."},{"key":"C","text":"It is plausible that between 54% and 62% of all registered voters in the city plan to vote in favor of the park expansion."},{"key":"D","text":"At most 62% of all registered voters in the city plan to vote in favor of the park expansion."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error defines a confidence interval around the sample statistic: 58% ± 4% gives a plausible range of 54% to 62% for the true population proportion. The statement that exactly 58% of all voters hold this view treats the sample statistic as the population parameter, ignoring sampling variability. The statement about the sampled voters misapplies the interval to the sample rather than the population — the sample result is already known. The statement about at most 62% captures only the upper bound and ignores the lower bound of the interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23B9AVT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist collects data on the length (in centimeters) and weight (in grams) of $29$ fish from a lake. The least-squares regression equation is $\\hat{w} = -193 + 17.6\\ell$, where $\\ell$ is length and $\\hat{w}$ is predicted weight. One fish has a length of $22$ cm and an actual weight of $231$ grams. What is the residual for this fish?', NULL, $lyceon_json$[{"key":"A","text":"$36.8$"},{"key":"B","text":"$-36.8$"},{"key":"C","text":"$231$"},{"key":"D","text":"$194.2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted weight is $\\hat{w} = -193 + 17.6(22) = -193 + 387.2 = 194.2$ grams. The residual is the actual value minus the predicted value: $231 - 194.2 = 36.8$. The distractor $-36.8$ reverses the subtraction order (predicted minus actual). The distractor $231$ gives the actual weight rather than the residual, misreading what the question asks. The distractor $194.2$ gives the predicted value, stopping before computing the residual.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23EF1UE', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges a flat fee of $\\$13$ plus $\\$4$ per package. A customer has a budget of no more than $\\$53$ for deliveries. Which inequality represents the number of packages $p$ the customer can have delivered, and what is the maximum number of packages?', NULL, $lyceon_json$[{"key":"A","text":"$13 + 4p \\leq 53$; at most $10$ packages"},{"key":"B","text":"$4 + 13p \\leq 53$; at most $3$ packages"},{"key":"C","text":"$13 + 4p < 53$; at most $9$ packages"},{"key":"D","text":"$13 + 4p \\geq 53$; at least $10$ packages"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is $13 + 4p$, and the budget constraint requires this to be at most $\\$53$, giving $13 + 4p \\leq 53$. Subtracting $13$ yields $4p \\leq 40$, so $p \\leq 10$. The maximum is $10$ packages. Swapping the coefficients to $4 + 13p$ reverses the flat fee and per-package rate, producing a much smaller maximum. Using strict inequality $<$ instead of $\\leq$ excludes the boundary case where cost equals exactly $\\$53$, giving $9$ instead of $10$. Reversing the inequality to $\\geq$ misinterprets the budget as a minimum spending requirement.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23H433T', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $g$ satisfies $g(2) = 13$ and $g(9) = -8$. What is the value of $g(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$\\frac{10}{3}$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $m = \\frac{-8 - 13}{9 - 2} = \\frac{-21}{7} = -3$. Using $g(2) = 13$: $g(x) = -3(x - 2) + 13 = -3x + 6 + 13 = -3x + 19$. Therefore $g(5) = -3(5) + 19 = -15 + 19 = 4$. The value $\\frac{10}{3}$ results from an arithmetic error when computing the slope or the intercept. The value $-2$ comes from a sign error, such as computing $-3(5) + 19$ as $15 - 19 = -4$ and then further mishandling the result. The value $10$ arises from computing only the change from $g(2)$, subtracting $3$ once instead of applying the slope formula across $3$ units of change.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23PYWKP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally priced at $\\$86$ is on sale for $\\$64.50$. What is the percent decrease in price?', NULL, $lyceon_json$[{"key":"A","text":"$21.5\\%$"},{"key":"B","text":"$25\\%$"},{"key":"C","text":"$33.3\\%$"},{"key":"D","text":"$75\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The decrease is $\\$86 - \\$64.50 = \\$21.50$. The percent decrease is $\\frac{21.50}{86} \\times 100 = 25\\%$. The value $21.5\\%$ uses the dollar decrease as the percentage without dividing by the original price. The value $33.3\\%$ divides by the sale price instead of the original. The value $75\\%$ represents the fraction of the original price remaining, not the decrease.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24PUW9P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe for a batch of dye requires $7$ grams of pigment for every $3$ liters of solvent. How many grams of pigment are needed for $9$ liters of solvent?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$21$"},{"key":"C","text":"$27$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of pigment to solvent is $\\frac{7}{3}$ grams per liter. For $9$ liters: $\\frac{7}{3} \\times 9 = 21$ grams. The distractor $14$ comes from doubling $7$ instead of tripling. The distractor $27$ results from multiplying the solvent amount by $3$ rather than using the pigment ratio. The distractor $63$ results from multiplying $7 \\times 9$ without accounting for the $3$-liter denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM275TUSS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ that satisfies $\\sqrt{2x + 7} = 9$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$37$"},{"key":"C","text":"$44$"},{"key":"D","text":"$-37$"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides gives $2x + 7 = 81$. Subtracting $7$ yields $2x = 74$, so $x = 37$. The distractor $1$ results from forgetting to square the right side and solving $2x + 7 = 9$ instead. The distractor $44$ comes from adding $7$ to $81$ instead of subtracting, giving $2x = 88$ and $x = 44$. The distractor $-37$ applies an incorrect sign when dividing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM283F76G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The mean of $6$ numbers is $47$. When a $7$th number is added, the new mean is $51$. What is the $7$th number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '75', ARRAY['75'], E'The sum of the original $6$ numbers is $6 \\times 47 = 282$. After adding the $7$th number, the sum of all $7$ numbers is $7 \\times 51 = 357$. Therefore the $7$th number is $357 - 282 = 75$. A common error is computing $51 - 47 = 4$ and adding that to $51$ to get $55$ (partial reasoning). Another error is computing $47 \\times 7 = 329$ and subtracting $282$ to get $47$ (using the old mean times the new count incorrectly).', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29P5FTZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $17$ centimeters and a width of $9$ centimeters. What is the area, in square centimeters, of the rectangle?', NULL, $lyceon_json$[{"key":"A","text":"$26$"},{"key":"B","text":"$52$"},{"key":"C","text":"$143$"},{"key":"D","text":"$153$"}]$lyceon_json$::jsonb, 'D', NULL, E'The area of a rectangle is length times width: $17 \\times 9 = 153$ square centimeters. The answer $52$ results from calculating the perimeter $2(17 + 9) = 52$ instead of the area. The answer $26$ comes from computing only $17 + 9 = 26$, which is half the perimeter. The answer $143$ results from an arithmetic error in multiplying $17 \\times 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AL3IG6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'If $\\frac{x^2 - 4x - 21}{x - 7} = 3x + 2$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$\\frac{1}{2}$"},{"key":"C","text":"$7$"},{"key":"D","text":"$-\\frac{1}{2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator: $x^2 - 4x - 21 = (x - 7)(x + 3)$. For $x \\neq 7$, the left side simplifies to $x + 3$. Setting $x + 3 = 3x + 2$ gives $1 = 2x$, so $x = \\frac{1}{2}$. The distractor $-3$ comes from setting the factor $(x + 3) = 0$, which is a root of the numerator but does not satisfy the original equation. The distractor $7$ comes from setting the denominator equal to zero, but $x = 7$ is excluded from the domain. The distractor $-\\frac{1}{2}$ results from a sign error when solving $1 = 2x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AT1YUF', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $7x - 3y = 42$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -14)$"},{"key":"B","text":"$(0, 14)$"},{"key":"C","text":"$(6, 0)$"},{"key":"D","text":"$(0, -6)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $y$-intercept occurs where $x = 0$. Substituting into $7x - 3y = 42$ gives $-3y = 42$, so $y = -14$. The $y$-intercept is $(0, -14)$. Choosing $(0, 14)$ neglects the negative sign. Choosing $(6, 0)$ gives the $x$-intercept instead. Choosing $(0, -6)$ results from dividing $42$ by $7$ rather than $3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BP8O05', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cone has a volume of $147\\pi$ cubic centimeters and a height of $9$ centimeters. What is the radius, in centimeters, of the base of the cone?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h$. Substituting the given values: $147\\pi = \\frac{1}{3}\\pi r^2 (9)$. Simplifying: $147\\pi = 3\\pi r^2$. Dividing both sides by $3\\pi$: $r^2 = 49$. Taking the positive square root: $r = 7$ centimeters.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C2Y9UO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveyed a random sample of 400 households in a county and found that the mean monthly electricity bill was \\$137 with a margin of error of \\$11 at the 95% confidence level. Which of the following conclusions is best supported by this information?', NULL, $lyceon_json$[{"key":"A","text":"Approximately 95% of households in the county have monthly electricity bills between \\$126 and \\$148."},{"key":"B","text":"The researcher is 95% confident that the mean monthly electricity bill for all households in the county is between \\$126 and \\$148."},{"key":"C","text":"If the survey were repeated, 95% of households sampled would report bills between \\$126 and \\$148."},{"key":"D","text":"Exactly 95% of all possible samples of 400 households would produce a sample mean of \\$137."}]$lyceon_json$::jsonb, 'B', NULL, E'A 95% confidence interval means the researcher is 95% confident that the true population mean falls within the interval $126 to $148. The claim that 95% of individual households fall in that range confuses the confidence interval for the mean with a prediction interval for individual values. The claim that 95% of sampled households in a repeated survey would fall in that range similarly misapplies the interval to individual observations rather than the mean. The claim that 95% of possible samples would produce a mean of exactly $137 mischaracterizes what the confidence level describes — it refers to the interval capturing the true mean, not to reproducing the exact sample mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C876QV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has a radius of $10$ centimeters. What is the area, in square centimeters, of a sector of the circle with a central angle of $54^\\circ$?', NULL, $lyceon_json$[{"key":"A","text":"$3\\pi$"},{"key":"B","text":"$15\\pi$"},{"key":"C","text":"$30\\pi$"},{"key":"D","text":"$100\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a sector is $\\frac{\\theta}{360} \\times \\pi r^2 = \\frac{54}{360} \\times \\pi(10)^2 = \\frac{3}{20} \\times 100\\pi = 15\\pi$ square centimeters. The answer $3\\pi$ results from applying the angle fraction to the circumference ($\\frac{54}{360} \\times 2\\pi(10) = 3\\pi$) instead of the area, confusing arc length with sector area. The answer $30\\pi$ results from dividing the angle by $180$ instead of $360$: $\\frac{54}{180} \\times 100\\pi = 30\\pi$. The answer $100\\pi$ results from computing the full circle area $\\pi(10)^2 = 100\\pi$ and ignoring the sector restriction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CH8MM4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $h$ is defined by $h(x) = a(x - b)^2 + c$, where $a$, $b$, and $c$ are positive constants. If $h(1) = 83$, $h(9) = 83$, and $h(5) = 3$, what is the value of $a + c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Because $h(1) = h(9) = 83$, the axis of symmetry is at $x = \\frac{1 + 9}{2} = 5$, so $b = 5$. Since the vertex is at $x = 5$, the minimum value is $h(5) = c = 3$. Substituting into $h(1) = 83$: $a(1 - 5)^2 + 3 = 83$, which gives $16a + 3 = 83$, so $16a = 80$ and $a = 5$. Therefore $a + c = 5 + 3 = 8$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D47GV6', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = -3x + 17$. What is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 4$: $f(4) = -3(4) + 17 = -12 + 17 = 5$. The value $29$ results from computing $3(4) + 17 = 29$, treating the coefficient as positive instead of negative. The value $-5$ reverses the addition, computing $-17 + 12$ instead of $-12 + 17$. The value $7$ arises from a miscalculation such as computing $-3(4) = -10$ and then adding $17$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DMLJH1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A student''s scores on $5$ quizzes are $73$, $81$, $88$, $81$, and $92$. What is the mode of these scores?', NULL, $lyceon_json$[{"key":"A","text":"$73$"},{"key":"B","text":"$81$"},{"key":"C","text":"$83$"},{"key":"D","text":"$88$"}]$lyceon_json$::jsonb, 'B', NULL, E'The mode is the value that appears most frequently. In the data set $\\{73, 81, 81, 88, 92\\}$, the value $81$ appears twice while all others appear once, so $81$ is the mode. The distractor $73$ is the minimum value, confusing mode with minimum. The distractor $83$ is the mean ($\\frac{73+81+88+81+92}{5} = 83$), confusing mode with mean. The distractor $88$ is neither the mode nor the median; a student might select it by confusing it with a central value, but the median of the ordered set is actually $81$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DQL1UY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $38^\\circ$ and the measure of angle $Q$ is $79^\\circ$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$53^\\circ$"},{"key":"B","text":"$63^\\circ$"},{"key":"C","text":"$73^\\circ$"},{"key":"D","text":"$117^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$, so angle $R = 180^\\circ - 38^\\circ - 79^\\circ = 63^\\circ$. The answer $117^\\circ$ results from adding $38 + 79 = 117$ and stopping without subtracting from $180$. The answer $73^\\circ$ results from a miscalculation of $180 - 117$ as $73$ instead of $63$. The answer $53^\\circ$ comes from incorrectly computing $38 + 79$ as $127$ and then finding $180 - 127 = 53$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DWRTIY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A health researcher analyzed hospital records and found that patients who were prescribed medication Z had a 31% lower rate of cardiac events over 5 years compared with patients who were not prescribed the medication. To strengthen the evidence that medication Z itself reduces cardiac events, which of the following study designs would be most appropriate?', NULL, $lyceon_json$[{"key":"A","text":"Conduct a larger observational study using records from multiple hospitals to increase the sample size."},{"key":"B","text":"Randomly assign eligible patients to receive either medication Z or a placebo, and compare cardiac event rates over 5 years."},{"key":"C","text":"Survey patients who were prescribed medication Z to determine whether they believe the medication improved their health."},{"key":"D","text":"Compare cardiac event rates between patients who chose to take medication Z and patients who chose not to take it, controlling for age only."}]$lyceon_json$::jsonb, 'B', NULL, E'To establish a causal relationship between medication Z and reduced cardiac events, a randomized controlled experiment is needed. Random assignment to medication Z or a placebo eliminates confounding variables, allowing the researcher to attribute differences in outcomes to the medication itself. A larger observational study increases sample size but does not address confounding — the association would remain observational regardless of scale. Surveying patients about their beliefs measures subjective perception, not clinical outcomes, and is irrelevant to establishing causation. Comparing self-selected groups while controlling for age only fails to account for the many other potential confounders (e.g., baseline health, lifestyle, socioeconomic status) and remains an observational design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F4B55P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers wanted to test whether a new fertilizer increases tomato yield. They randomly assigned 60 tomato plants in a greenhouse to two groups of 30: one group received the new fertilizer and the other received the standard fertilizer. After 8 weeks, the mean yield for the new-fertilizer group was 7.4 kg per plant and for the standard-fertilizer group was 5.9 kg per plant. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer caused an increase in tomato yield compared with the standard fertilizer for the plants in the study."},{"key":"B","text":"The new fertilizer will increase tomato yield for all tomato varieties grown in any environment."},{"key":"C","text":"Plants that received the new fertilizer tended to produce more tomatoes, but the difference could be due to other variables."},{"key":"D","text":"Because the sample size is only 30 per group, no valid conclusion can be drawn from this experiment."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the plants were randomly assigned to treatment groups, this is a controlled experiment, and a causal conclusion is appropriate for the plants in the study: the new fertilizer caused the observed increase. The claim that it will increase yield for all tomato varieties in any environment overgeneralizes beyond the scope of this greenhouse experiment. The claim that the difference could be due to other variables incorrectly treats this as an observational study — random assignment controls for confounding variables. The claim that no conclusion can be drawn because of the sample size is incorrect; 30 per group is a reasonable sample size, and random assignment supports causal inference regardless.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F8GMQ1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bookstore has 37 novels on a shelf: 14 are mystery novels, 9 are science fiction novels, and 14 are romance novels. If a customer selects one novel at random from the shelf, what is the probability that it is a science fiction novel?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{9}{37}\\)"},{"key":"B","text":"\\(\\dfrac{14}{37}\\)"},{"key":"C","text":"\\(\\dfrac{9}{28}\\)"},{"key":"D","text":"\\(\\dfrac{9}{23}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The probability of selecting a science fiction novel is the number of science fiction novels divided by the total number of novels: 9/37. The distractor 14/37 results from selecting the count of mystery or romance novels instead of science fiction. The distractor 9/28 incorrectly subtracts the science fiction novels from the total before forming the fraction, treating the denominator as the count of non-science-fiction books. The distractor 9/23 uses an incorrect total from an arithmetic error (14 + 9 = 23, omitting the second group of 14).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FRLPRO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher models the relationship between the age of a car (in years) and its resale value (in thousands of dollars) with the equation $\\hat{y} = 31.4 - 2.7x$, where $x$ is the age and $\\hat{y}$ is the predicted resale value. What is the best interpretation of the slope?', NULL, $lyceon_json$[{"key":"A","text":"For each additional year of age, the predicted resale value decreases by $\\$2{,}700$."},{"key":"B","text":"For each additional year of age, the predicted resale value increases by $\\$2{,}700$."},{"key":"C","text":"A new car (age $0$) has a predicted resale value of $\\$2{,}700$."},{"key":"D","text":"For each $\\$1{,}000$ decrease in resale value, the car ages by $2.7$ years."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $-2.7$ means that for each one-unit increase in $x$ (one additional year of age), $\\hat{y}$ decreases by $2.7$ thousand dollars, or $\\$2{,}700$. The distractor claiming the value increases ignores the negative sign. The distractor claiming a new car is worth $\\$2{,}700$ confuses the slope ($-2.7$) with the $y$-intercept ($31.4$). The distractor inverting the relationship misinterprets the slope as $\\frac{\\Delta x}{\\Delta y}$ instead of $\\frac{\\Delta y}{\\Delta x}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FTLR3C', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $\\frac{18x^5 y^3}{6x^2 y}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x^3 y^2$"},{"key":"B","text":"$3x^3 y^3$"},{"key":"C","text":"$12x^3 y^2$"},{"key":"D","text":"$3x^7 y^4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing the coefficients gives $\\frac{18}{6} = 3$. For the $x$ terms, subtract exponents: $x^{5-2} = x^3$. For the $y$ terms, subtract exponents: $y^{3-1} = y^2$. The simplified expression is $3x^3 y^2$. The distractor $3x^3 y^3$ results from failing to subtract the $y$ exponent. The distractor $12x^3 y^2$ results from subtracting the coefficients ($18 - 6 = 12$) instead of dividing. The distractor $3x^7 y^4$ results from adding the exponents instead of subtracting, which confuses the multiplication and division rules for exponents.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G0GKTH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees at a company recorded whether each employee commutes by car or by train and whether each works in the marketing or engineering department. Of the 200 employees, 118 commute by car and 82 commute by train. Of those who commute by car, 43 work in marketing. Of those who commute by train, 51 work in engineering. Given that a randomly selected employee works in engineering, what is the probability that the employee commutes by car?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{75}{126}\\)"},{"key":"B","text":"\\(\\dfrac{75}{118}\\)"},{"key":"C","text":"\\(\\dfrac{75}{200}\\)"},{"key":"D","text":"\\(\\dfrac{43}{118}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Of the 118 car commuters, 43 work in marketing, so 118 − 43 = 75 work in engineering. Of the 82 train commuters, 51 work in engineering. The total number of engineering employees is 75 + 51 = 126. The conditional probability that an engineering employee commutes by car is 75/126. The distractor 75/118 divides by the total car commuters rather than the total engineering employees, confusing P(engineering | car) with P(car | engineering). The distractor 75/200 divides by the total number of employees, giving the joint probability rather than the conditional probability. The distractor 43/118 uses the number of marketing car commuters divided by total car commuters, answering the wrong conditional question entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HMS1EY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of hours studied and test scores for $20$ students. The line of best fit has a positive slope. Which of the following best describes the association shown?', NULL, $lyceon_json$[{"key":"A","text":"As study hours increase, test scores tend to increase."},{"key":"B","text":"As study hours increase, test scores tend to decrease."},{"key":"C","text":"There is no association between study hours and test scores."},{"key":"D","text":"Increasing study hours causes higher test scores."}]$lyceon_json$::jsonb, 'A', NULL, E'A positive slope on the line of best fit indicates a positive association: as the explanatory variable (hours studied) increases, the response variable (test scores) tends to increase. The distractor stating scores tend to decrease describes a negative slope. The distractor stating no association contradicts the existence of a line of best fit with a nonzero slope. The distractor claiming causation confuses correlation with causation — a scatterplot shows association, not a causal relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IL32II', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'What is the value of $x$ in the solution to the system of equations below?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ILLJUZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A factory produces $413$ widgets in $7$ hours. At the same rate, how many complete widgets can the factory produce in $11$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$589$"},{"key":"B","text":"$649$"},{"key":"C","text":"$660$"},{"key":"D","text":"$693$"}]$lyceon_json$::jsonb, 'B', NULL, E'The production rate is $\\frac{413}{7} = 59$ widgets per hour. In $11$ hours: $59 \\times 11 = 649$ widgets. The distractor $589$ comes from a computational slip such as calculating $59 \\times 10 - 1$. The distractor $660$ arises from rounding the rate to $60$ per hour. The distractor $693$ results from computing $\\frac{413}{7} \\times 11$ incorrectly as $63 \\times 11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J9ZWV5', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A plumber charges a flat fee of $\\$47$ for a service call plus $\\$31$ per hour of labor. An electrician charges a flat fee of $\\$83$ plus $\\$19$ per hour. For how many hours of work would both professionals charge the same total amount?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$4$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the two charges equal: $47 + 31h = 83 + 19h$. Subtracting $19h$ from both sides: $47 + 12h = 83$. Subtracting $47$: $12h = 36$. Dividing by $12$: $h = 3$. The answer $2$ results from setting up the equation incorrectly, such as reversing the flat fees. The answer $4$ comes from an arithmetic slip when dividing $36$ by $12$. The answer $6$ arises from dividing $36$ by the difference in flat fees ($6 = 36/6$) instead of by the difference in hourly rates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KC9221', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'If $3x - 7 > 14$, which of the following must be true?', NULL, $lyceon_json$[{"key":"A","text":"$x > 7$"},{"key":"B","text":"$x > 3$"},{"key":"C","text":"$x < 7$"},{"key":"D","text":"$x > -7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $7$ to both sides gives $3x > 21$. Dividing both sides by $3$ gives $x > 7$. The distractor $x > 3$ results from dividing $21$ by $7$ instead of by $3$. The distractor $x < 7$ incorrectly reverses the inequality direction. The distractor $x > -7$ comes from subtracting $14$ from $7$ rather than adding $7$ to $14$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KOFR6Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $DEF$, the measure of angle $D$ is $(3x + 11)^\\circ$, the measure of angle $E$ is $(2x - 7)^\\circ$, and the measure of angle $F$ is $(4x + 5)^\\circ$. What is the measure, in degrees, of the smallest angle of the triangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '31', ARRAY['31'], E'The sum of the angles in a triangle is $180^\\circ$, so $(3x + 11) + (2x - 7) + (4x + 5) = 180$. Combining like terms gives $9x + 9 = 180$, so $9x = 171$ and $x = 19$. Substituting back: angle $D = 3(19) + 11 = 68^\\circ$, angle $E = 2(19) - 7 = 31^\\circ$, and angle $F = 4(19) + 5 = 81^\\circ$. The smallest angle is $31^\\circ$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L7G4KP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Lines $p$ and $q$ are parallel, and a transversal $t$ intersects line $p$ at point $A$ and line $q$ at point $B$. The measure of one of the angles formed at $A$ on the same side of the transversal as $B$ is $137^\\circ$. What is the measure, in degrees, of the same-side interior angle formed at $B$?', NULL, $lyceon_json$[{"key":"A","text":"$37^\\circ$"},{"key":"B","text":"$43^\\circ$"},{"key":"C","text":"$53^\\circ$"},{"key":"D","text":"$137^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'Same-side interior angles formed by two parallel lines and a transversal are supplementary, meaning they add up to $180^\\circ$. Therefore the angle at $B$ is $180^\\circ - 137^\\circ = 43^\\circ$. The answer $137^\\circ$ results from confusing same-side interior angles with corresponding angles, which are congruent. The answer $53^\\circ$ results from confusing supplementary with complementary and computing $90^\\circ - 37^\\circ$. The answer $37^\\circ$ comes from an arithmetic slip in subtracting $137$ from $180$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LAULDL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $h$ is defined by $h(x) = 5x^2 - 11$. What is the value of $h(-4)$?', NULL, $lyceon_json$[{"key":"A","text":"$59$"},{"key":"B","text":"$69$"},{"key":"C","text":"$91$"},{"key":"D","text":"$-91$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = -4$ into $h(x) = 5x^2 - 11$ gives $h(-4) = 5(-4)^2 - 11 = 5(16) - 11 = 80 - 11 = 69$. The value $59$ results from computing $5(16) - 21$. The value $91$ results from computing $5(16) + 11$. The value $-91$ results from incorrectly applying the negative sign to the entire expression.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MDML1U', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A small business owner produces two types of candles: standard and deluxe. Each standard candle requires $2$ hours of labor and each deluxe candle requires $5$ hours. The owner has at most $47$ hours of labor available per week and must produce at least $3$ deluxe candles to fulfill standing orders. If $s$ represents the number of standard candles and $d$ represents the number of deluxe candles, what is the maximum number of standard candles the owner can produce in one week?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$16$"},{"key":"C","text":"$21$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'B', NULL, E'The constraints are $2s + 5d \\leq 47$ and $d \\geq 3$. To maximize $s$, set $d$ to its minimum value of $3$. Substituting gives $2s + 15 \\leq 47$, so $2s \\leq 32$, and $s \\leq 16$. The maximum is $16$ standard candles. The value $13$ results from mistakenly using $d = 4$ instead of the minimum $d = 3$, which gives $2s + 20 \\leq 47$, so $2s \\leq 27$ and $s \\leq 13$. The value $21$ comes from subtracting only one deluxe candle''s labor of $5$ hours instead of three, giving $(47 - 5) / 2 = 21$. The value $23$ results from ignoring the deluxe candle requirement entirely and computing $\\lfloor 47 / 2 \\rfloor$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MY5499', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $33$ and $56$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$89$"},{"key":"B","text":"$63$"},{"key":"C","text":"$65$"},{"key":"D","text":"$\\sqrt{89}$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the Pythagorean theorem, the hypotenuse is $\\sqrt{33^2 + 56^2} = \\sqrt{1089 + 3136} = \\sqrt{4225} = 65$. The value $89$ comes from adding the legs directly. The value $63$ results from a computational error in the square root. The expression $\\sqrt{89}$ comes from adding the legs under the radical without squaring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OQ8SV6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A surveyor stands $37$ meters from the base of a building. The angle of elevation from the surveyor to the top of the building is $\\alpha$, where $\\tan(\\alpha) = \\frac{15}{37}$. A flagpole sits on top of the building. The angle of elevation from the surveyor to the top of the flagpole is $\\beta$, where $\\tan(\\beta) = \\frac{19}{37}$. What is the height, in meters, of the flagpole?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Using the tangent ratio, the height of the building is $37 \\times \\frac{15}{37} = 15$ meters. The total height from the ground to the top of the flagpole is $37 \\times \\frac{19}{37} = 19$ meters. Therefore, the height of the flagpole alone is $19 - 15 = 4$ meters.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OT6CCC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A marine biologist is converting water salinity measurements. She records $37$ grams of salt per kilogram of seawater. If the density of the seawater is $1.03$ kilograms per liter, how many grams of salt are in $5$ liters of this seawater, rounded to the nearest whole number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '191', ARRAY['191'], E'First, find the mass of $5$ liters of seawater: $5 \\times 1.03 = 5.15$ kilograms. Then multiply by the salinity: $5.15 \\times 37 = 190.55$ grams, which rounds to $191$ grams. A common error is ignoring the density conversion and computing $5 \\times 37 = 185$. Another error is multiplying $37 \\times 1.03 = 38.11$ and stopping (partial reasoning). A third error is computing $37 \\times 5 \\times 1.03$ but rounding incorrectly to $190$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PKOF6O', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $9x - 23 = 58$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$\\frac{35}{9}$"},{"key":"C","text":"$-9$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $23$ to both sides gives $9x = 81$, and dividing both sides by $9$ gives $x = 9$. The value $\\frac{35}{9}$ results from subtracting $23$ from $58$ to get $35$ and then dividing by $9$, rather than adding $23$ to $58$ first. The value $-9$ comes from a sign error when dividing $81$ by $9$. The value $4$ arises from a miscalculation such as dividing $58 - 23 = 35$ by $9$ and rounding incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q2X5ME', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'The equation $x^2 + y^2 - 6x + 14y + 33 = 0$ defines a circle in the $xy$-plane. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'To find the radius, complete the square for both $x$ and $y$ terms. Group the terms: $(x^2 - 6x) + (y^2 + 14y) = -33$. Complete the square for $x$: $x^2 - 6x + 9 = (x - 3)^2$. Complete the square for $y$: $y^2 + 14y + 49 = (y + 7)^2$. Adding $9$ and $49$ to both sides: $(x - 3)^2 + (y + 7)^2 = -33 + 9 + 49 = 25$. This is a circle with center $(3, -7)$ and radius $\\sqrt{25} = 5$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QO1T0F', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $13$ meters. What is the circumference, in meters, of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$13\\pi$"},{"key":"B","text":"$26\\pi$"},{"key":"C","text":"$52\\pi$"},{"key":"D","text":"$169\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = 2\\pi r = 2\\pi(13) = 26\\pi$ meters. The answer $13\\pi$ results from using $\\pi r$ instead of $2\\pi r$, omitting the factor of $2$. The answer $52\\pi$ results from substituting the diameter $26$ into the circumference formula as though it were the radius, computing $2\\pi(26)$. The answer $169\\pi$ results from computing the area $\\pi r^2 = \\pi(13)^2 = 169\\pi$ instead of the circumference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QOMUXS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'A jar contains tokens labeled with the integers $1$ through $10$. Two tokens are drawn at random without replacement. What is the probability that both tokens show a prime number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2/15', ARRAY['2/15', '0.133', '.133'], E'The prime numbers from 1 to 10 are 2, 3, 5, and 7, giving 4 primes. The probability that the first token drawn is prime is 4/10. Given that the first token is prime, 3 primes remain among 9 tokens, so the probability the second is also prime is 3/9. Multiplying: (4/10)(3/9) = 12/90 = 2/15. A common error is computing 4/10 × 4/10, which treats the draws as with replacement. Another common error is miscounting the primes, such as including 1 as prime.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R0LZS3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'In $2023$, a town''s population was $4{,}500$. The population increased by $8\\%$ from $2023$ to $2024$ and then decreased by $5\\%$ from $2024$ to $2025$. What was the town''s population in $2025$, rounded to the nearest whole number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4617', ARRAY['4617'], E'From $2023$ to $2024$: $4{,}500 \\times 1.08 = 4{,}860$. From $2024$ to $2025$: $4{,}860 \\times 0.95 = 4{,}617$. Therefore the population in $2025$ is $4{,}617$. A common error is computing $4{,}500 \\times 1.03 = 4{,}635$ by simply adding the net percentage ($8\\% - 5\\% = 3\\%$), which ignores that the decrease applies to the larger intermediate value. Another error is applying the $5\\%$ decrease to the original population: $4{,}500 \\times 0.95 = 4{,}275$, then adding $8\\%$ of $4{,}500$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RA14KN', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'In the system of equations below, $k$ is a constant.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S4LFJ5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization conducts two independent random surveys about support for a new transit line. Survey X polls 600 likely voters and finds 47% support with a margin of error of 4.1 percentage points. Survey Y polls 1,500 likely voters and finds 52% support with a margin of error of 2.6 percentage points. Which of the following statements is best supported by the results of both surveys?', NULL, $lyceon_json$[{"key":"A","text":"The two surveys contradict each other, so at least one must have used a biased sampling method."},{"key":"B","text":"Because the confidence intervals overlap, the data are consistent with a true level of support between about 49% and 51%."},{"key":"C","text":"Survey Y is more reliable because it surveyed more voters, so 52% is the best estimate of the true support level."},{"key":"D","text":"The true proportion of likely voters who support the transit line is exactly 49.5%, the average of the two survey results."}]$lyceon_json$::jsonb, 'B', NULL, E'Survey X yields a confidence interval of approximately 42.9% to 51.1%, and Survey Y yields approximately 49.4% to 54.6%. These intervals overlap in the range of about 49.4% to 51.1%, meaning the data are consistent with a true proportion in that overlapping zone. The claim that the surveys contradict each other ignores that overlapping confidence intervals indicate compatibility. While Survey Y does have a smaller margin of error due to its larger sample, simply declaring its point estimate the best estimate ignores that both surveys provide useful information and their intervals overlap. Averaging the two point estimates to get exactly 49.5% and treating that as the true proportion is a misuse of statistics — an average of sample proportions from different-sized samples is not a valid inference procedure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SA5F5N', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = 3x^2 + 18x + 41$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$41$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$-14$"}]$lyceon_json$::jsonb, 'A', NULL, E'Completing the square: $f(x) = 3(x^2 + 6x) + 41 = 3(x^2 + 6x + 9 - 9) + 41 = 3(x + 3)^2 - 27 + 41 = 3(x + 3)^2 + 14$. Since $3(x + 3)^2 \\geq 0$, the minimum value of $f(x)$ is $14$, occurring at $x = -3$. The distractor $41$ comes from using only the constant term of the original expression without completing the square. The distractor $-3$ is the $x$-coordinate of the vertex, not the minimum value of the function. The distractor $-14$ applies an incorrect sign to the minimum value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T7MS0N', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sold $174$ tickets for a performance. Adult tickets cost $\\$11$ each and student tickets cost $\\$7$ each. If the total revenue from ticket sales was $\\$1{,}534$, how many student tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$79$"},{"key":"B","text":"$87$"},{"key":"C","text":"$95$"},{"key":"D","text":"$103$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $a$ represent adult tickets and $s$ represent student tickets. The system is $a + s = 174$ and $11a + 7s = 1{,}534$. Substituting $a = 174 - s$ into the revenue equation gives $11(174 - s) + 7s = 1{,}534$, which simplifies to $1{,}914 - 11s + 7s = 1{,}534$, then $-4s = -380$, so $s = 95$. The value $79$ is the number of adult tickets, not student tickets. The value $87$ results from an arithmetic error when computing $1{,}914 - 1{,}534$. The value $103$ comes from incorrectly swapping the ticket prices in the revenue equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TA951K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A school district compared test scores of students who participated in an after-school tutoring program with those who did not. Students chose whether or not to participate. The district found that students in the tutoring program scored an average of 23 points higher on the end-of-year exam. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The tutoring program caused the 23-point increase in test scores."},{"key":"B","text":"Students who chose to participate in the tutoring program tended to score higher on the end-of-year exam than those who did not."},{"key":"C","text":"If all students had participated in the tutoring program, the average score would have increased by 23 points."},{"key":"D","text":"The tutoring program had no real effect because the study was not randomized."}]$lyceon_json$::jsonb, 'B', NULL, E'Because students self-selected into the tutoring program, this is an observational study, not an experiment. The appropriate conclusion is an association: students who chose to participate tended to score higher. The causal claim that the program caused the increase is not justified because confounding variables (e.g., motivation, prior achievement) may explain the difference. The claim that all students would gain 23 points assumes a causal effect and generalizes it universally, both of which are unsupported. The claim that the program had no real effect goes too far in the opposite direction — a non-randomized study cannot establish causation, but it does not prove the absence of an effect either.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VPD10W', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, $\\sin(\\theta) = \\frac{20}{29}$. What is the value of $\\cos(\\theta)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{29}$"},{"key":"B","text":"$\\frac{20}{21}$"},{"key":"C","text":"$\\frac{21}{29}$"},{"key":"D","text":"$\\frac{29}{21}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\sin(\\theta) = \\frac{20}{29}$, the opposite side is $20$ and the hypotenuse is $29$. By the Pythagorean theorem, the adjacent side is $\\sqrt{29^2 - 20^2} = \\sqrt{841 - 400} = \\sqrt{441} = 21$. Therefore $\\cos(\\theta) = \\frac{21}{29}$. The answer $\\frac{9}{29}$ comes from subtracting $29 - 20 = 9$ instead of using the Pythagorean theorem. The answer $\\frac{20}{21}$ confuses cosine with tangent (opposite over adjacent). The answer $\\frac{29}{21}$ inverts the cosine ratio, computing secant instead of cosine.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W49IEQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'What is the positive solution to $2x^2 + 7x - 15 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3/2', ARRAY['3/2', '1.5'], E'Using the quadratic formula: $x = \\frac{-7 \\pm \\sqrt{49 + 120}}{4} = \\frac{-7 \\pm \\sqrt{169}}{4} = \\frac{-7 \\pm 13}{4}$. This gives $x = \\frac{6}{4} = \\frac{3}{2}$ or $x = \\frac{-20}{4} = -5$. The positive solution is $\\frac{3}{2}$. Alternatively, factoring: $2x^2 + 7x - 15 = (2x - 3)(x + 5) = 0$, giving $x = \\frac{3}{2}$ or $x = -5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WCICVM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'A water tank is being drained at a constant rate. At $t = 7$ minutes, the tank contains $206$ liters, and at $t = 23$ minutes, it contains $78$ liters. At what time, in minutes, will the tank be completely empty?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '131/4', ARRAY['131/4', '32.75'], E'The rate of change is $\\frac{78 - 206}{23 - 7} = \\frac{-128}{16} = -8$ liters per minute. Using the point $(7, 206)$, the volume function is $V(t) = -8(t - 7) + 206 = -8t + 56 + 206 = -8t + 262$. Setting $V(t) = 0$: $8t = 262$, so $t = \\frac{262}{8} = \\frac{131}{4}$. The tank will be completely empty at $t = \\frac{131}{4}$ minutes, or equivalently $32.75$ minutes.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WSFKRP', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(2, 11)$ and $(7, 31)$. What is the $x$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-3/4', ARRAY['-3/4', '-0.75', '-.75'], E'The slope is $m = \\frac{31 - 11}{7 - 2} = \\frac{20}{5} = 4$. Using point-slope form with $(2, 11)$: $y - 11 = 4(x - 2)$, which simplifies to $y = 4x + 3$. Setting $y = 0$: $0 = 4x + 3$, so $4x = -3$ and $x = -\\frac{3}{4}$. The $x$-intercept is $-\\frac{3}{4}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YALTCM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store marks up a wholesale item by $40\\%$ to set the retail price. During a clearance event, the retail price is then reduced by $15\\%$. What is the overall percent change from the wholesale price to the clearance price?', NULL, $lyceon_json$[{"key":"A","text":"$19\\%$ increase"},{"key":"B","text":"$25\\%$ increase"},{"key":"C","text":"$35\\%$ increase"},{"key":"D","text":"$55\\%$ increase"}]$lyceon_json$::jsonb, 'A', NULL, E'Let the wholesale price be $100$. The markup gives $100 \\times 1.40 = 140$. The $15\\%$ reduction gives $140 \\times 0.85 = 119$. The overall change from $100$ to $119$ is a $19\\%$ increase. The distractor $25\\%$ comes from subtracting $15$ from $40$. The distractor $35\\%$ results from an arithmetic slip when computing the successive percentages. The distractor $55\\%$ comes from adding $40\\%$ and $15\\%$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z1XU04', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(3x + 7)^2 - (3x - 7)^2$?', NULL, $lyceon_json$[{"key":"A","text":"$84x$"},{"key":"B","text":"$0$"},{"key":"C","text":"$18x^2 + 98$"},{"key":"D","text":"$42x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Expanding $(3x + 7)^2 = 9x^2 + 42x + 49$ and $(3x - 7)^2 = 9x^2 - 42x + 49$. Subtracting: $(9x^2 + 42x + 49) - (9x^2 - 42x + 49) = 42x + 42x = 84x$. The distractor $0$ reflects the misconception that $(a + b)^2$ and $(a - b)^2$ are identical. The distractor $18x^2 + 98$ results from adding the two expansions instead of subtracting. The distractor $42x$ comes from only accounting for one of the two middle terms in the subtraction rather than combining both.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZEYYFR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $5x + 8y = 40$. Line $q$ is perpendicular to line $p$ and passes through the point $(3, -2)$. What is the equation of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$y = \\frac{8}{5}x - \\frac{34}{5}$"},{"key":"B","text":"$y = -\\frac{5}{8}x - \\frac{1}{8}$"},{"key":"C","text":"$y = \\frac{8}{5}x + \\frac{34}{5}$"},{"key":"D","text":"$y = \\frac{5}{8}x - \\frac{31}{8}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting $5x + 8y = 40$ in slope-intercept form gives $y = -\\frac{5}{8}x + 5$, so line $p$ has slope $-\\frac{5}{8}$. A perpendicular line has slope equal to the negative reciprocal: $\\frac{8}{5}$. Using point-slope form through $(3, -2)$: $y + 2 = \\frac{8}{5}(x - 3)$, giving $y = \\frac{8}{5}x - \\frac{24}{5} - \\frac{10}{5} = \\frac{8}{5}x - \\frac{34}{5}$. The equation $y = -\\frac{5}{8}x - \\frac{1}{8}$ uses the original slope of line $p$ instead of the perpendicular slope. The equation $y = \\frac{8}{5}x + \\frac{34}{5}$ uses the correct perpendicular slope but applies an incorrect sign to the constant term. The equation $y = \\frac{5}{8}x - \\frac{31}{8}$ uses the reciprocal of line $p$''s slope without negating it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZKUIHZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ if $4(3x - 7) = 2(5x + 3) + 8$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'Distribute on both sides: $12x - 28 = 10x + 6 + 8$, which simplifies to $12x - 28 = 10x + 14$. Subtract $10x$ from both sides: $2x - 28 = 14$. Add $28$ to both sides: $2x = 42$. Divide by $2$: $x = 21$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZR4QEY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set has $11$ values listed in ascending order: $4, 7, 9, 12, 15, 18, 21, 23, 26, 29, 31$. If the value $31$ is replaced with $97$, which of the following measures will change?', NULL, $lyceon_json$[{"key":"A","text":"Median only"},{"key":"B","text":"Mean only"},{"key":"C","text":"Both the median and the mean"},{"key":"D","text":"Neither the median nor the mean"}]$lyceon_json$::jsonb, 'B', NULL, E'With $11$ values, the median is the $6$th value in order, which is $18$. Replacing $31$ (the largest value) with $97$ does not change the $6$th position, so the median remains $18$. However, the sum increases by $97 - 31 = 66$, so the mean increases from $\\frac{195}{11}$ to $\\frac{261}{11}$. Therefore only the mean changes. The distractor claiming only the median changes reflects a misunderstanding of how outliers affect central tendency. The distractor claiming both change incorrectly assumes replacing an extreme value shifts the middle position. The distractor claiming neither changes ignores that the mean depends on the sum of all values.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZY1PZL', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $x > 0$, $x > \\frac{1}{x}$, and $x^2 + \\frac{1}{x^2} = 51$, what is the value of $x - \\frac{1}{x}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Recognize that $\\left(x - \\frac{1}{x}\\right)^2 = x^2 - 2 \\cdot x \\cdot \\frac{1}{x} + \\frac{1}{x^2} = x^2 - 2 + \\frac{1}{x^2}$. Substituting the given value: $\\left(x - \\frac{1}{x}\\right)^2 = 51 - 2 = 49$. Since $x > 0$ and $x > \\frac{1}{x}$, the quantity $x - \\frac{1}{x}$ is positive, so $x - \\frac{1}{x} = \\sqrt{49} = 7$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20L70EN', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Neuroscientist Ádám Takács and his team examined whether bilingual individuals outperform monolinguals on tasks requiring cognitive flexibility. Their 2023 meta-analysis of 147 studies found no statistically significant advantage for bilinguals on standard task-switching measures. _______ the team identified a narrow exception: bilinguals who had acquired both languages before age three showed marginally faster response times on tasks involving conflicting sensory cues, though only under high cognitive load.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"That said,"},{"key":"C","text":"In addition,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage first reports that the meta-analysis found no significant bilingual advantage overall. The sentence after the blank then introduces a narrow exception to that general finding — a specific subgroup under specific conditions did show a small advantage. "That said" correctly signals a concession or qualification that partially counters the preceding negative finding without fully reversing it. "Similarly" wrongly implies the exception mirrors the general finding, when it actually qualifies it. "In addition" treats the exception as merely additional information of the same type, missing the crucial concessive relationship between a null finding and its exception. "Accordingly" wrongly implies the exception follows logically from the null result, when it actually complicates it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW221NQFX', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Linguist Sofiya Malenkov studied code-switching patterns among trilingual speakers of Russian, Georgian, and Azerbaijani in the city of Rustavi. She found that speakers consistently switched to Russian when discussing technology, finance, and formal bureaucratic matters, to Georgian for family narratives and emotional expression, and to Azerbaijani for humor and proverbs. Notably, when Malenkov asked participants to retell a humorous family anecdote—a scenario combining two of these pragmatic domains—most speakers began in Georgian but switched to Azerbaijani at the punchline. Malenkov argues that this pattern indicates that code-switching in multilingual communities is governed not by random preference but by ________', $lyceon_json$[{"key":"A","text":"domain-specific communicative functions that each language has come to serve within the community's social practice."},{"key":"B","text":"the relative grammatical complexity of each language, with speakers defaulting to whichever language has the simplest syntax for a given topic."},{"key":"C","text":"a speaker's level of fluency in each language, with the most fluent language used for the most cognitively demanding tasks."},{"key":"D","text":"the formality of the setting in which the conversation takes place, with more formal contexts always prompting a switch to Russian."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that each language is consistently associated with particular communicative functions—Russian for formal/technical topics, Georgian for family and emotion, Azerbaijani for humor—and that even in mixed scenarios, speakers switch languages at the point where the communicative function shifts. This supports the conclusion that code-switching is governed by domain-specific functions each language serves. The option about grammatical complexity introduces a factor the passage never discusses. The option about fluency levels is unsupported; the passage does not suggest speakers are more fluent in one language than another. The option about formality alone is too narrow—while Russian is used for formal contexts, the passage also shows language choice varying by emotional and humorous functions, which are not purely matters of formality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24RETTK', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the acoustic analysis conducted by the forensic team nor the spectral readings obtained from the seismograph _______ consistent with the mining company''s claim that the underground detonation occurred at the reported depth of forty-seven meters.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"has been"},{"key":"D","text":"is being"}]$lyceon_json$::jsonb, 'B', NULL, E'In a ''neither...nor'' construction, subject-verb agreement follows the proximity rule: the verb agrees with the noun nearest to it. The nearer subject is ''the spectral readings,'' which is plural, so the verb must be plural as well. ''Were'' is the correct plural past-tense form. ''Was'' is singular and does not agree with the plural nearer subject ''readings.'' ''Has been'' is singular present perfect, which fails both in number agreement with the plural nearer subject and in tense consistency with the past-tense context established by ''occurred.'' ''Is being'' is singular present progressive, which likewise fails in number and tense.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW258J4TX', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1953, biochemist Erwin Chargaff published data showing that in any DNA sample, the amount of adenine roughly equals the amount of thymine, and the amount of guanine roughly equals the amount of cytosine. These base-pairing ratios, however, were initially dismissed by several prominent geneticists who viewed them as coincidental artifacts of Chargaff''s limited sample set. It was not until Watson and Crick proposed their double-helix model — in which adenine pairs specifically with thymine and guanine with cytosine — that Chargaff''s ratios were recognized as reflecting a fundamental structural principle rather than a statistical anomaly.', $lyceon_json$[{"key":"A","text":"It presents a finding, describes the initial resistance to that finding, and then explains how the finding was ultimately vindicated."},{"key":"B","text":"It compares two competing scientific theories and argues that one is superior to the other."},{"key":"C","text":"It traces the biographical development of a scientist from early career to major achievement."},{"key":"D","text":"It describes an experimental procedure in chronological order and evaluates its accuracy."}]$lyceon_json$::jsonb, 'A', NULL, E'The text follows a three-part structure: first presenting Chargaff''s base-pairing data, then noting that prominent geneticists dismissed the ratios as coincidental, and finally explaining how Watson and Crick''s double-helix model vindicated Chargaff''s findings. The text does not compare two competing theories — Chargaff''s ratios and Watson and Crick''s model are complementary, not competing. The text does not trace a biographical arc of a scientist''s career; it focuses on the reception of a specific finding. The text does not describe an experimental procedure step by step or evaluate its accuracy; it describes the reception and eventual validation of a result.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW271LXAH', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ceramic artist Yolanda Treviño has spent over nineteen years perfecting a glaze technique inspired by volcanic _______ her recent exhibition at the Museo de Arte Contemporáneo featured thirty-seven vessels finished in this signature style.', $lyceon_json$[{"key":"A","text":"minerals,"},{"key":"B","text":"minerals;"},{"key":"C","text":"minerals"},{"key":"D","text":"minerals, and,"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank joins two independent clauses: one about Treviño''s years perfecting a glaze technique and another about her recent exhibition. A semicolon correctly links two independent clauses without a coordinating conjunction. A comma alone after ''minerals'' creates a comma splice, which is a sentence boundary error. Omitting all punctuation after ''minerals'' produces a run-on sentence. Adding a comma with ''and'' plus an extra comma after ''and'' introduces unnecessary punctuation that disrupts the sentence''s grammatical structure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28LYL70', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Tromsø have long studied the effects of prolonged darkness on human circadian rhythms. Their findings suggest that residents of Arctic regions experience measurable shifts in melatonin production during the polar night. _______ these shifts do not appear to cause lasting health consequences for most individuals, as the body gradually adapts to seasonal light changes.', $lyceon_json$[{"key":"A","text":"However,"},{"key":"B","text":"Furthermore,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank states that measurable shifts in melatonin production occur, while the sentence containing the blank introduces the contrasting idea that these shifts do not cause lasting health problems. The contrast transition "However" correctly signals this shift from a potentially concerning finding to a reassuring outcome. "Furthermore" wrongly signals addition rather than contrast. "For instance" wrongly signals an example. "Consequently" wrongly implies the absence of health consequences is a direct result of the melatonin shifts, which reverses the logical relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28M48VQ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Mycorrhizal networks — fungal filaments that connect the root systems of different plants — allow mature trees to transfer carbon and nutrients to younger seedlings growing in shade. Ecologist Suzanne Simard has documented that Douglas fir seedlings receiving such transfers show significantly higher survival rates. _______ Simard''s subsequent research revealed that trees under attack by bark beetles increase nutrient transfers to neighboring healthy trees, suggesting the network may function as a communal defense mechanism rather than merely a passive conduit.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"By contrast,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage first establishes that mycorrhizal networks transfer resources to seedlings, improving their survival. The sentence after the blank introduces an additional, more surprising finding: trees under attack increase transfers to healthy neighbors, suggesting an active defense function. "Moreover" correctly signals that this new finding builds on and extends the previous evidence. "Nevertheless" wrongly implies the new finding contradicts the earlier one, but both support the importance of the network. "Specifically" wrongly implies the beetle-attack finding is a particular instance of the seedling-survival finding, when it is actually a distinct phenomenon that broadens the scope of the network''s function. "By contrast" wrongly signals opposition between two findings that are complementary.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
