INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AO0L25', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ethnomusicologist Miriam Castañeda, who spent eleven years documenting polyphonic singing traditions in the Caucasus, _______ that the oldest surviving practitioners of the Svan harvest chant technique were all born before 1938.', $lyceon_json$[{"key":"A","text":"noting"},{"key":"B","text":"has noted"},{"key":"C","text":"to have noted"},{"key":"D","text":"note"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject ''The ethnomusicologist Miriam Castañeda'' is singular and requires a finite verb to complete the main clause. The intervening relative clause beginning with ''who spent eleven years'' is a nonessential modifier set off by commas and does not change the subject. ''Has noted'' is the correct singular present-perfect form, indicating a finding that resulted from completed research and remains relevant. The participle ''noting'' is non-finite and would leave the sentence without a main verb, producing a fragment. The infinitive ''to have noted'' is also non-finite and cannot serve as the predicate of the main clause. The bare plural form ''note'' does not agree with the singular subject ''The ethnomusicologist Miriam Castañeda.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B536L9', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the third sentence in the text?', E'Historian Amara Osei-Mensah has challenged the prevailing characterization of the 1874 Sagrenti War as a straightforward colonial conquest. She points out that the Asante military command employed a sophisticated intelligence network that intercepted British dispatches and anticipated troop movements weeks in advance. Osei-Mensah argues that the eventual British victory owed less to tactical superiority than to the Asante leadership''s strategic miscalculation in committing reserves to defend a secondary fortification at Amoaful rather than concentrating forces at the Pra River crossing. Her analysis draws on recently declassified Asante oral histories that record deliberations among war captains about whether to prioritize territorial defense or force preservation.', $lyceon_json$[{"key":"A","text":"It provides Osei-Mensah's explanation for an outcome that her earlier claims might otherwise leave unexplained."},{"key":"B","text":"It introduces a counterargument to the position Osei-Mensah established in the previous sentences."},{"key":"C","text":"It offers a concession that weakens Osei-Mensah's overall thesis about the conflict."},{"key":"D","text":"It supplies biographical context about Osei-Mensah's qualifications as a historian."}]$lyceon_json$::jsonb, 'A', NULL, E'The first two sentences establish that the Asante military was sophisticated and well-prepared, which raises the question of why the British ultimately won. The third sentence resolves this by arguing the British victory resulted from a specific Asante strategic miscalculation, not British tactical superiority — thus providing Osei-Mensah''s explanation for an outcome her earlier claims might leave unexplained. The sentence does not introduce a counterargument; it extends Osei-Mensah''s own thesis by explaining how the British won despite Asante competence. It does not concede a weakness in her thesis; rather, it strengthens her argument by attributing the outcome to a specific strategic error rather than inherent inferiority. It contains no biographical information about Osei-Mensah''s qualifications.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
