INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FKK0PW', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at the Lund University Cognitive Science department discovered that Eurasian jays can exercise a form of self-control when presented with delayed food _______ the birds consistently refused an immediately available mealworm in favor of waiting for a preferred piece of cheese that appeared after a variable delay of up to five and a half minutes.', $lyceon_json$[{"key":"A","text":"rewards, specifically,"},{"key":"B","text":"rewards. Specifically,"},{"key":"C","text":"rewards specifically,"},{"key":"D","text":"rewards, specifically"}]$lyceon_json$::jsonb, 'B', NULL, E'The text contains two independent clauses: the first describes the researchers'' discovery about self-control, and the second provides a specific example of that behavior. Using a period after ''rewards'' and beginning a new sentence with ''Specifically,'' correctly separates the two independent clauses while the transitional adverb signals that the second clause elaborates on the first. Using a comma after ''rewards'' followed by ''specifically,'' produces a comma splice joining two independent clauses. Placing ''specifically'' without preceding punctuation after ''rewards'' creates a run-on sentence. Omitting the comma after ''specifically'' fails to properly set off the conjunctive adverb from the independent clause it introduces.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IES9MU', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every summer, the municipal orchestra of Regensburg _______ a series of open-air concerts in the Stadtpark, drawing audiences of over two thousand residents each weekend.', $lyceon_json$[{"key":"A","text":"perform"},{"key":"B","text":"have performed"},{"key":"C","text":"performs"},{"key":"D","text":"are performing"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is ''the municipal orchestra,'' which is a singular noun requiring a singular verb. The phrase ''of Regensburg'' is a prepositional modifier and does not affect subject-verb agreement. ''Performs'' is the correct singular present-tense form matching the habitual action signaled by ''Every summer.'' The bare form ''perform'' is plural and does not agree with the singular subject. ''Have performed'' is plural and also shifts to the present perfect tense, which conflicts with the habitual present indicated by ''Every summer.'' ''Are performing'' is plural and shifts to the present progressive, which does not match the habitual meaning.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KHFP0B', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which choice best describes data from the table that would support Okoro''s conclusion over Petersen''s?', E'Economists Ngozi Okoro and Lars Petersen disagree about what drove the 2017–2021 decline in copper extraction rates in Zambia''s Copperbelt Province. Okoro argues that declining ore grades—the percentage of copper recoverable per ton of rock—forced mines to process more material for less output, making extraction economically unviable at prevailing prices. Petersen counters that extraction declined primarily because of regulatory changes enacted in 2018 that increased royalty rates from 6 percent to 10 percent of gross revenue, discouraging continued investment. A government mining report contains the following data for Copperbelt Province: average ore grade fell from 2.3 percent in 2017 to 1.4 percent in 2021; extraction costs per ton of refined copper rose 58 percent over the same period; copper prices on the London Metal Exchange increased 27 percent between 2017 and 2021; and three of the seven major mines had announced expansion plans before the 2018 royalty increase but canceled them afterward.', $lyceon_json$[{"key":"A","text":"The data showing ore grade dropped from 2.3 percent to 1.4 percent while extraction costs per ton rose 58 percent, because these figures indicate that deteriorating geological conditions made mining progressively less economical."},{"key":"B","text":"The data showing that three mines canceled expansion plans after the 2018 royalty increase, because this suggests regulatory changes directly influenced investment decisions."},{"key":"C","text":"The data showing copper prices rose 27 percent, because higher global prices should have incentivized more extraction if other factors were not constraining output."},{"key":"D","text":"The combination of rising copper prices and canceled expansion plans, because together they demonstrate that external market conditions were favorable but domestic policy drove the decline."}]$lyceon_json$::jsonb, 'A', NULL, E'Okoro''s argument centers on declining ore grades making extraction uneconomical. The data showing ore grade fell from 2.3 to 1.4 percent while costs rose 58 percent directly supports her geological-economic explanation: worse ore required more processing at higher cost per unit of output. The data about canceled expansion plans after the royalty increase supports Petersen''s regulatory explanation, not Okoro''s. The observation that copper prices rose 27 percent could be used as supplementary context by either side but does not itself demonstrate that ore-grade decline drove the extraction decrease—it merely shows prices were not the constraining factor. The combination of rising prices and canceled plans supports Petersen''s argument that domestic policy was the decisive factor, which is the opposite of what the question asks for.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KRWW5N', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The playwright Lorraine Hansberry drew on her family''s experience with racially restrictive housing covenants in _______ father, Carl Hansberry, had fought the practice all the way to the Supreme Court in the 1940 case Hansberry v. Lee, which challenged the enforceability of such agreements in Chicago neighborhoods.', $lyceon_json$[{"key":"A","text":"Chicago. Her"},{"key":"B","text":"Chicago, her"},{"key":"C","text":"Chicago: her"},{"key":"D","text":"Chicago her"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses are present: the first states that Hansberry drew on her family''s experience with housing covenants in Chicago, and the second provides background about her father''s Supreme Court case. A period after ''Chicago'' correctly separates these two independent clauses into distinct sentences. A comma after ''Chicago'' produces a comma splice, improperly joining two independent clauses with only a comma. A colon after ''Chicago'' is incorrect because the second clause does not explain, define, or elaborate on ''Chicago'' — it introduces a new subject (her father) and a new historical fact. Omitting punctuation entirely produces a run-on sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LIXLIE', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the biologist had hypothesized that the high-altitude beetle species would exhibit reduced metabolic rates, the laboratory results _______ that metabolic output actually increased under simulated alpine conditions.', $lyceon_json$[{"key":"A","text":"indicating"},{"key":"B","text":"indicated"},{"key":"C","text":"having indicated"},{"key":"D","text":"to indicate"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence requires a finite verb to serve as the main predicate of the independent clause beginning with ''the laboratory results.'' The past tense ''indicated'' correctly provides a finite verb that agrees with the plural subject ''results'' and maintains tense consistency with ''had hypothesized'' in the subordinate clause. The present participle ''indicating'' is a non-finite form that would leave the independent clause without a main verb, creating a sentence fragment. The perfect participle ''having indicated'' is also non-finite and cannot serve as the main predicate. The infinitive ''to indicate'' is non-finite and would similarly produce a fragment rather than a complete clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MKXT70', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'In a 2019 analysis of municipal water infrastructure across seventeen Appalachian counties, civil engineer Priya Nagarajan found that pipe corrosion rates had ______ over the preceding decade, a trend she attributed to increasingly acidic groundwater interacting with aging cast-iron mains installed in the 1940s.', $lyceon_json$[{"key":"A","text":"accelerated"},{"key":"B","text":"originated"},{"key":"C","text":"dissolved"},{"key":"D","text":"competed"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that corrosion rates changed over a decade due to increasingly acidic groundwater, indicating the rates increased in speed. "Accelerated" means increased in rate or speed, which fits precisely. "Originated" means began or started, but the passage describes a change in existing rates, not the beginning of corrosion. "Dissolved" refers to a physical process of breaking down in liquid; while related to corrosion conceptually, it describes what happens to the pipes themselves, not what happened to the rates. "Competed" implies rivalry between entities, which makes no sense when describing corrosion rates.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N0FNKP', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The Ming dynasty''s maritime expeditions under Admiral Zheng He reached as far as the eastern coast of Africa between 1405 and 1433, demonstrating China''s unrivaled naval capabilities during that era. After the Xuande Emperor''s death, however, the imperial court abruptly halted these voyages and destroyed most of the fleet''s records. _______ some historians have argued that the decision reflected a philosophical shift toward Confucian inward focus, while others attribute it to budgetary pressures from northern border conflicts.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"As a result,"},{"key":"C","text":"In any case,"},{"key":"D","text":"To this end,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes the abrupt halt of the voyages and then presents competing scholarly interpretations of why the court made that decision. The transition "In any case" correctly signals that regardless of the specific reasons, historians have offered multiple explanations. "In other words" wrongly implies the following sentence restates the previous one, but it introduces new scholarly debate rather than rephrasing. "As a result" wrongly implies the historians'' arguments were caused by the destruction of records, conflating the historical event with the academic response. "To this end" wrongly implies the historians'' arguments serve the purpose of halting the voyages, which is nonsensical.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N4WBM0', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary about tidal energy and wants to present a balanced view by acknowledging both a key advantage and a significant limitation. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NJSNPE', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologists studying the Mariana Trench have documented organisms that thrive under pressures exceeding 1,000 atmospheres. The creatures'' ability to survive in such ______ conditions has prompted researchers to reconsider the boundaries of habitability on other planetary bodies.', $lyceon_json$[{"key":"A","text":"extreme"},{"key":"B","text":"artificial"},{"key":"C","text":"temporary"},{"key":"D","text":"ornamental"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes organisms surviving under pressures exceeding 1,000 atmospheres in the Mariana Trench, which are harsh and intense environmental conditions. "Extreme" precisely captures this meaning. "Artificial" implies human-made conditions, which contradicts the natural deep-sea setting. "Temporary" suggests the conditions are short-lived, but the passage describes a permanent environment. "Ornamental" means decorative, which is entirely unrelated to the harsh pressure conditions described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NSYH4O', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a proposal for a geology seminar and wants to argue that a specific volcanic formation challenges a widely held geological assumption. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O770CO', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit of the New Zealand kauri tree (Agathis australis) takes approximately 18 months to mature after pollination, one of the longest seed-development periods of any conifer species. During this time, the developing cones remain tightly sealed and attached high in the canopy, beyond the reach of most ground-dwelling seed predators. Researchers studying kauri regeneration have noted that seedlings appear almost exclusively in canopy gaps created by fallen mature trees rather than beneath intact canopy. This pattern suggests that successful kauri germination depends on ________', $lyceon_json$[{"key":"A","text":"direct sunlight reaching the forest floor, a condition typically met only where gaps in the canopy exist."},{"key":"B","text":"protection from wind damage provided by surrounding mature trees."},{"key":"C","text":"the presence of mycorrhizal fungi that are unique to kauri root systems."},{"key":"D","text":"soil temperatures that remain constant throughout the year."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that kauri seedlings appear almost exclusively in canopy gaps created by fallen trees rather than under intact canopy. The most logical completion is that germination depends on direct sunlight reaching the forest floor, which would occur precisely in such gaps. The option about wind protection contradicts the observed pattern, since seedlings appear in exposed gaps rather than sheltered areas. The option about unique mycorrhizal fungi introduces a factor the passage never mentions. The option about constant soil temperatures is unsupported by anything in the text and does not explain the gap-specific distribution of seedlings.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q1R698', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Neuroscientist Elara Voss and her colleagues recently investigated the long-standing assumption that hippocampal volume correlates directly with spatial navigation ability in London taxi drivers. While earlier studies by Maguire et al. (2000) found enlarged posterior hippocampi in experienced drivers, Voss''s team used higher-resolution diffusion tensor imaging on 83 drivers with between 4 and 31 years of experience. Their results confirmed the volumetric enlargement but revealed an unexpected complication: drivers with more than 19 years of experience showed reduced white-matter connectivity between the hippocampus and the prefrontal cortex compared to drivers with 10 to 15 years of experience. Voss suggests that prolonged reliance on deeply encoded spatial maps may paradoxically weaken the flexible, goal-directed planning circuits that originally supported route learning, a phenomenon she terms "navigational entrenchment."', $lyceon_json$[{"key":"A","text":"Voss's research replicates earlier findings about hippocampal enlargement in taxi drivers but also uncovers a decline in neural connectivity that complicates the assumed relationship between brain structure and navigational skill."},{"key":"B","text":"Voss's study contradicts the Maguire findings entirely by showing that hippocampal volume does not actually increase in experienced taxi drivers."},{"key":"C","text":"Taxi drivers with the most experience have the best spatial navigation abilities because their hippocampi are the largest of any professional group studied."},{"key":"D","text":"Reduced white-matter connectivity in the prefrontal cortex is a general consequence of aging that Voss mistakenly attributes to taxi driving specifically."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Voss confirmed the earlier volumetric finding but discovered an unexpected reduction in white-matter connectivity among the most experienced drivers, introducing the concept of navigational entrenchment. The option noting that her research replicates the enlargement finding while uncovering a complicating connectivity decline captures both dimensions of the main idea. The option claiming Voss contradicts Maguire entirely misrepresents the results, since the passage states her team confirmed the volumetric enlargement. The option asserting the most experienced drivers have the best navigation abilities directly opposes the passage''s point about navigational entrenchment weakening flexible planning circuits. The option attributing the connectivity reduction to general aging introduces a claim the passage never makes and mischaracterizes Voss''s argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q88LRE', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing an article about the culinary uses of saffron and wants to emphasize its economic significance. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ROAOR2', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the claim made in the text?', E'In a 2023 review article, ornithologist Priya Dasgupta asserts that the recent population recovery of the Mauritius kestrel—from just four wild individuals in 1974 to over 400 by 2019—demonstrates that intensive captive breeding programs are sufficient on their own to reverse the decline of critically endangered raptor species, provided that enough breeding pairs can be established in controlled facilities.', $lyceon_json$[{"key":"A","text":"The Mauritius kestrel recovery involved not only captive breeding but also large-scale habitat restoration, invasive predator removal, and supplemental feeding, all of which were conducted simultaneously."},{"key":"B","text":"Several other raptor species, including the California condor, have also benefited from captive breeding initiatives over the past five decades."},{"key":"C","text":"The genetic diversity of the current Mauritius kestrel population is significantly lower than that of most other falcon species."},{"key":"D","text":"Dasgupta's review article was published in a journal that primarily focuses on conservation genetics rather than field ecology."}]$lyceon_json$::jsonb, 'A', NULL, E'Dasgupta claims captive breeding alone is sufficient to reverse raptor decline. The finding that the Mauritius kestrel recovery also involved habitat restoration, predator removal, and supplemental feeding directly undermines the claim that captive breeding was sufficient on its own, since multiple concurrent interventions contributed to the outcome. The finding about other raptor species benefiting from captive breeding supports rather than weakens the claim. The observation about reduced genetic diversity raises a concern about long-term viability but does not address whether captive breeding alone drove the population recovery. The detail about the journal''s focus is irrelevant to the scientific validity of the claim itself.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2THOU43', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Ethnomusicologist Tunde Adeyinka has argued that the Yoruba dundun drum tradition cannot be adequately understood through Western musicological frameworks alone. According to Adeyinka, the tonal inflections of the dundun do not merely accompany spoken Yoruba but actually ______ it, reproducing the language''s pitch contours with sufficient fidelity that fluent speakers can decode full sentences from the drum patterns without any verbal accompaniment.', $lyceon_json$[{"key":"A","text":"replicate"},{"key":"B","text":"contradict"},{"key":"C","text":"precede"},{"key":"D","text":"regulate"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explains that the dundun drum reproduces Yoruba pitch contours with enough fidelity that speakers can decode full sentences from drum patterns alone. "Replicate" means to reproduce or copy, which precisely matches the description of the drum faithfully reproducing the language''s tonal patterns. "Contradict" means to oppose or deny, but the passage describes the drum faithfully reproducing speech, not opposing it. "Precede" means to come before in time, but the passage discusses the drum reproducing speech patterns, not occurring before speech historically. "Regulate" means to control or govern, but the passage describes the drum copying speech patterns, not controlling them.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UNUFP0', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The violet-backed starling (Cinnyricinclus leucogaster) exhibits one of the most striking cases of sexual dimorphism among sub-Saharan passerines. Males display an iridescent amethyst plumage across the head, back, and wings, while females are covered in mottled brown and white feathers. <u>This dramatic visual contrast has made the species a frequent subject of studies examining the role of sexual selection in plumage evolution.</u> Recent work by ornithologist Fumiko Hasegawa has traced the iridescence to nanostructures in the feather barbules that produce color through light interference rather than pigmentation.', $lyceon_json$[{"key":"A","text":"It explains why a particular research topic has attracted scientific attention."},{"key":"B","text":"It provides evidence that contradicts a claim made earlier in the passage."},{"key":"C","text":"It introduces a technical methodology used in a specific study."},{"key":"D","text":"It defines a key scientific term for the reader."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence states that the dramatic visual contrast has made the species a frequent subject of studies on sexual selection in plumage evolution. This explains why the species attracts scientific interest — connecting the previously described dimorphism to its significance as a research topic. The sentence does not contradict anything stated earlier; it builds on the description of sexual dimorphism. It does not introduce a technical methodology — the following sentence about Hasegawa''s work does that. It does not define a scientific term; it explains the consequence of the visual contrast for research interest.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UXCBLN', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Paleobotanist Jun Nakashima examined fossilized leaf morphology from 14 late Cretaceous sites across what is now the Northern Great Plains. At sites dated between 68 and 66 million years ago—the final two million years before the end-Cretaceous extinction event—Nakashima found a progressive increase in the proportion of leaves with smooth (entire) margins relative to those with toothed (serrated) margins. In modern ecosystems, the proportion of entire-margined species in a regional flora correlates positively with mean annual temperature: tropical forests have roughly 75 percent entire-margined species, while temperate forests have only 30 to 40 percent. Applying this relationship to his fossil data, Nakashima estimates that mean annual temperatures in the Northern Great Plains rose by approximately 4 degrees Celsius during this interval. However, some critics note that the sites spanning this two-million-year window also show a marked decrease in overall plant species diversity, with the number of distinct leaf morphotypes declining by nearly half. These critics argue that the shift toward entire-margined leaves may therefore reflect not warming but rather ________', $lyceon_json$[{"key":"A","text":"the selective extinction of toothed-margin species due to factors unrelated to temperature, which would artificially inflate the proportion of entire-margined species in the fossil record without any actual climate change."},{"key":"B","text":"an evolutionary adaptation in which individual plant species developed smoother leaf margins in response to increased atmospheric carbon dioxide concentrations."},{"key":"C","text":"a preservation bias in younger sedimentary layers that favored the fossilization of thicker, entire-margined leaves over thinner, toothed leaves."},{"key":"D","text":"the migration of tropical plant species into the Northern Great Plains from equatorial regions, displacing the native toothed-margin flora entirely."}]$lyceon_json$::jsonb, 'A', NULL, E'The critics note that species diversity declined sharply during the same interval, which opens an alternative explanation: if toothed-margin species went extinct at higher rates than entire-margined species for reasons other than temperature, the surviving flora would have a higher proportion of entire-margined leaves without any actual warming. This is the only option that directly addresses the critics'' observation about declining diversity. The option about evolutionary adaptation to carbon dioxide introduces a mechanism the passage never mentions and does not account for the diversity decline. The option about preservation bias invokes a taphonomic factor not raised in the passage and unrelated to the critics'' specific point about species loss. The option about tropical migration would actually support a warming interpretation rather than offering an alternative to it, and it overstates by claiming complete displacement.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VBQOYA', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 1971, microbiologist Thomas D. Brock published his discovery of Thermus aquaticus, a bacterium thriving in the scalding waters of Yellowstone''s hot springs at temperatures exceeding 70 degrees Celsius. At the time, most scientists assumed that life could not persist above 55 degrees Celsius. Brock''s finding overturned that assumption and opened an entirely new field of research into thermophilic organisms—life forms adapted to extreme heat. Within two decades, an enzyme derived from Thermus aquaticus, called Taq polymerase, became the cornerstone of the polymerase chain reaction (PCR), a technique now indispensable to genetics, forensics, and medical diagnostics worldwide.', $lyceon_json$[{"key":"A","text":"Brock's discovery of a heat-tolerant bacterium challenged existing biological assumptions and ultimately enabled a transformative laboratory technique."},{"key":"B","text":"The polymerase chain reaction was developed in the 1990s as a direct result of research conducted in Yellowstone National Park."},{"key":"C","text":"Scientists before Brock were largely uninterested in studying organisms that lived in geothermal environments."},{"key":"D","text":"Thermus aquaticus was the first organism ever found in a hot spring, which surprised the scientific community."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces how Brock''s discovery of a bacterium living above 70 degrees Celsius upended the assumption that life could not survive above 55 degrees, and then explains that an enzyme from that bacterium became central to PCR technology. The option stating that the discovery challenged assumptions and enabled a transformative technique captures both elements. The option about PCR being developed in the 1990s as a direct result of Yellowstone research distorts the timeline and causal chain presented. The option claiming scientists were uninterested in geothermal organisms goes beyond what the text says—it states they assumed life could not persist at high temperatures, not that they were uninterested. The option asserting Thermus aquaticus was the first organism found in a hot spring is unsupported; the passage does not make that claim.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VEEB8Q', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Agricultural scientists at the Orinoco Basin Research Station hypothesize that cassava plants grown in iron-rich laterite soils produce higher concentrations of cyanogenic glucosides—natural toxins that deter herbivory—than cassava grown in sandy alluvial soils. The researchers propose that elevated iron availability triggers a metabolic pathway that increases cyanogenic glucoside synthesis as a defense response.', $lyceon_json$[{"key":"A","text":"Cassava plants transplanted from alluvial soil to laterite soil showed a 40 percent increase in cyanogenic glucoside levels within three growing seasons."},{"key":"B","text":"Laterite soils in the Orinoco Basin contain on average twice as much iron as alluvial soils in the same region."},{"key":"C","text":"Cassava is one of the most widely cultivated crops in tropical regions and serves as a dietary staple for over 800 million people."},{"key":"D","text":"Herbivorous insects in the Orinoco Basin prefer feeding on cassava leaves over those of other root vegetables."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis claims that cassava in iron-rich laterite soil produces more cyanogenic glucosides than cassava in alluvial soil. The finding that transplanting cassava from alluvial to laterite soil caused a 40 percent increase in these compounds directly demonstrates the proposed causal link between soil type and toxin production. The finding about laterite soils containing more iron merely confirms a background condition; it does not show that this iron difference affects glucoside production in the plants. The information about cassava''s global cultivation is irrelevant to the specific soil-chemistry hypothesis. The observation about insect feeding preferences addresses herbivore behavior rather than the plant''s chemical response to soil composition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YU36LS', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, the conservationist Wangari Maathai expanded her Green Belt Movement beyond its original tree-planting _______ civic education and advocacy for environmental governance, a shift that positioned the organization as a political force in Kenyan public life.', $lyceon_json$[{"key":"A","text":"mission, encompassing"},{"key":"B","text":"mission. Encompassing"},{"key":"C","text":"mission; encompassing"},{"key":"D","text":"mission encompassing"}]$lyceon_json$::jsonb, 'A', NULL, E'The participial phrase beginning with ''encompassing'' modifies the main clause by describing how Maathai expanded the movement; it is not an independent clause. A comma after ''mission'' correctly introduces this modifying participial phrase. A period after ''mission'' would create a sentence fragment beginning with ''Encompassing,'' since a participial phrase cannot stand alone as a sentence. A semicolon after ''mission'' is incorrect because semicolons join independent clauses, and the participial phrase is not independent. Omitting all punctuation after ''mission'' would make ''encompassing'' appear to begin a restrictive modifier of ''mission,'' distorting the sentence''s meaning by suggesting the expansion was limited to the original mission rather than extending beyond it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZO6634', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Historian Mariana Quevedo argues that the collapse of the Wari Empire around 1000 CE was not, as traditionally believed, a sudden catastrophe triggered by prolonged drought. Instead, Quevedo''s analysis of ceramic distribution patterns across 37 archaeological sites in the Ayacucho Basin reveals a gradual, regionalized fragmentation spanning at least 150 years. In the northern provinces, Wari administrative centers were abandoned by approximately 900 CE, while southern centers continued to function—and even expanded—until roughly 1050 CE. Quevedo contends that this staggered pattern is more consistent with a slow erosion of political cohesion than with a single environmental shock.', $lyceon_json$[{"key":"A","text":"Quevedo challenges the conventional explanation for the Wari Empire's collapse by presenting evidence of a drawn-out, uneven decline rather than an abrupt event."},{"key":"B","text":"Quevedo has demonstrated that environmental factors played no role whatsoever in the dissolution of the Wari Empire."},{"key":"C","text":"The Wari Empire's southern provinces were more culturally advanced than its northern provinces, which explains their longer survival."},{"key":"D","text":"Ceramic artifacts found at 37 sites prove that the Wari Empire's administrative systems were more complex than those of any contemporary civilization."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Quevedo''s argument that the Wari collapse was gradual and regionally staggered rather than sudden, supported by ceramic evidence from multiple sites. The option about challenging the conventional explanation with evidence of a drawn-out decline accurately captures this central idea. The option claiming environmental factors played no role overstates Quevedo''s position—she argues against drought as the sole sudden trigger, not that environment was entirely irrelevant. The option about southern provinces being more culturally advanced introduces a claim the passage never makes; it notes the south continued functioning longer but attributes no cultural superiority. The option about Wari administrative complexity exceeding that of all contemporary civilizations extrapolates far beyond the passage''s actual claims about ceramic distribution.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
